  /* 各市区县企业数：按固定权重拆分全市总量（无锡用手写口径覆盖），区县名来自真实边界数据 */
  if (window.JXMAP) {
    const WTS = [0.24, 0.18, 0.145, 0.115, 0.09, 0.07, 0.055, 0.045, 0.035, 0.025];
    jsOverview.cityDistricts = {};
    Object.keys(window.JXMAP.cities).forEach(cn => {
      const names = window.JXMAP.cities[cn].map(x => x.n);
      const total = (jsOverview.cities.find(c => c.n === cn.replace('市', '')) || {}).v || 1200;
      const wts = WTS.slice(0, names.length);
      const wsum = wts.reduce((s, x) => s + x, 0);
      jsOverview.cityDistricts[cn] = names.map((n, i) => ({ n, v: Math.max(60, Math.round(total * wts[i] / wsum)) }));
    });
    jsOverview.cityDistricts['无锡市'] = jsOverview.wxCities.filter(x => window.JXMAP.cities['无锡市'].some(d => d.n === x.n));
  }

